import { randomUUID } from "node:crypto";
import { DomainError, NotFoundError } from "../domain/errors";
import { Order, OrderLine, OrderState } from "../domain/order";
import { OrderRepository, ProductRepository } from "../domain/repositories";
import { Product } from "../domain/product";

export interface PlaceOrderItem {
  productId: string;
  quantity: number;
}

export interface OrderView {
  id: string;
  customerId: string;
  state: OrderState;
  cancelled: boolean;
  items: readonly OrderLine[];
}

export interface ProductView {
  id: string;
  name: string;
  availableStock: number;
}

export class FulfilmentService {
  public constructor(
    private readonly products: ProductRepository,
    private readonly orders: OrderRepository,
  ) {}

  public addProduct(id: string, name: string, stock: number): ProductView {
    const product = new Product(id, name, stock);
    if (this.products.findById(id)) throw new DomainError(`Product '${id}' already exists.`);
    this.products.save(product);
    return this.toProductView(product);
  }

  public listProducts(): ProductView[] {
    return this.products.list().map((product) => this.toProductView(product));
  }

  public placeOrder(customerId: string, items: readonly PlaceOrderItem[]): OrderView {
    const requested = this.combineItems(items);
    const products = requested.map(({ productId, quantity }) => ({
      product: this.requireProduct(productId),
      quantity,
    }));

    // Validate every line before changing stock, keeping an unsuccessful request atomic.
    for (const { product, quantity } of products) {
      if (product.availableStock < quantity) {
        throw new DomainError(`Insufficient stock for product '${product.id}'.`);
      }
    }
    for (const { product, quantity } of products) product.reserve(quantity);

    const order = new Order(randomUUID(), customerId, requested);
    this.orders.save(order);
    return this.toOrderView(order);
  }

  public advanceOrder(id: string, nextState: OrderState): OrderView {
    const order = this.requireOrder(id);
    order.advanceTo(nextState);
    this.orders.save(order);
    return this.toOrderView(order);
  }

  public cancelOrder(id: string): OrderView {
    const order = this.requireOrder(id);
    order.cancel();
    for (const line of order.lines) this.requireProduct(line.productId).release(line.quantity);
    this.orders.save(order);
    return this.toOrderView(order);
  }

  public listOrders(state?: OrderState): OrderView[] {
    return this.orders.list(state).map((order) => this.toOrderView(order));
  }

  public getOrder(id: string): OrderView {
    return this.toOrderView(this.requireOrder(id));
  }

  private combineItems(items: readonly PlaceOrderItem[]): OrderLine[] {
    if (items.length === 0) throw new DomainError("An order must contain at least one item.");
    const quantities = new Map<string, number>();
    for (const item of items) {
      if (!item.productId?.trim()) throw new DomainError("A product id is required for every item.");
      if (!Number.isSafeInteger(item.quantity) || item.quantity <= 0) {
        throw new DomainError("Quantity must be a positive integer.");
      }
      quantities.set(item.productId, (quantities.get(item.productId) ?? 0) + item.quantity);
    }
    return [...quantities].map(([productId, quantity]) => ({ productId, quantity }));
  }

  private requireProduct(id: string): Product {
    const product = this.products.findById(id);
    if (!product) throw new NotFoundError("Product", id);
    return product;
  }

  private requireOrder(id: string): Order {
    const order = this.orders.findById(id);
    if (!order) throw new NotFoundError("Order", id);
    return order;
  }

  private toProductView(product: Product): ProductView {
    return { id: product.id, name: product.name, availableStock: product.availableStock };
  }

  private toOrderView(order: Order): OrderView {
    return { id: order.id, customerId: order.customerId, state: order.state, cancelled: order.cancelled, items: order.lines };
  }
}

